-- Baseline: the schema exactly as Hibernate's ddl-auto:update left it, captured from
-- pg_dump of the live database. Existing environments are baselined at V1 and never
-- run this file; it exists so a brand-new environment builds an identical schema.
--
-- Do not edit this file to change the schema. Add a new V<n>__*.sql instead, so the
-- change reaches existing databases too.

CREATE TABLE notifications (
    id              uuid                        NOT NULL,
    attempts        integer                     NOT NULL,
    channel         varchar(255)                NOT NULL,
    created_at      timestamp(6) with time zone NOT NULL,
    failure_reason  varchar(255),
    idempotency_key varchar(255),
    message         varchar(255)                NOT NULL,
    recipient       varchar(255)                NOT NULL,
    sent_at         timestamp(6) with time zone,
    status          varchar(255)                NOT NULL,
    tenant_id       uuid,

    CONSTRAINT notifications_pkey PRIMARY KEY (id),

    CONSTRAINT notifications_channel_check
        CHECK (channel IN ('EMAIL', 'SMS', 'PUSH')),

    -- Every value of NotificationStatus, SENDING included. SENDING is the state the
    -- atomic PENDING -> SENDING claim writes (NotificationRepository.claimForSending);
    -- omitting it here would make every delivery claim fail on a fresh database.
    CONSTRAINT notifications_status_check
        CHECK (status::text = ANY (ARRAY['PENDING'::text, 'SENDING'::text, 'SENT'::text, 'FAILED'::text, 'DEAD'::text])),

    -- Idempotency is scoped to the tenant: two tenants may reuse the same key.
    -- NULLs are distinct in Postgres, so key-less notifications never collide.
    CONSTRAINT uk_notifications_tenant_idempotency_key UNIQUE (tenant_id, idempotency_key)
);

-- Serves countByStatus(PENDING), polled every 5s by MetricsPoller.
CREATE INDEX idx_notifications_status ON notifications USING btree (status);

-- Serves the created_at ordering on the list endpoints.
CREATE INDEX idx_notifications_created_at ON notifications USING btree (created_at);

CREATE INDEX idx_notifications_status_created_at ON notifications USING btree (status, created_at);

CREATE TABLE tenants (
    id                    uuid         NOT NULL,
    api_key               varchar(255) NOT NULL,
    name                  varchar(255) NOT NULL,
    rate_limit_per_minute integer      NOT NULL,

    CONSTRAINT tenants_pkey PRIMARY KEY (id),

    -- Hibernate-generated constraint names, kept verbatim so a fresh database matches
    -- the existing one exactly. Renaming them would be a schema change, and therefore
    -- belongs in its own migration.
    CONSTRAINT uk3en99tewvbc4g3a7ou4mt1ono UNIQUE (api_key),
    CONSTRAINT uk4moql6miwoh3w0drxa2gmjbll UNIQUE (name)
);
